public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // validate input arguments
    if (genericType == null || !genericType.isParameterized() || targetType == null) {
        return null;
    }

    // get the type variable map for the target type
    Map<TypeVariable<?>, Type> typeVariableMap = targetType.getTypeVariableMap();

    // get the type arguments for the generic type
    Type[] typeArguments = genericType.getTypeArguments();

    // create an array to store the resolved arguments
    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];

    // resolve each type argument
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument.isParameterized()) {
            // get the type variable for the type argument
            TypeVariable<?> typeVariable = ((ParameterizedType) typeArgument).getTypeVariable();

            // resolve the type variable using the type variable map
            Type resolvedTypeArgument = typeVariableMap.get(typeVariable);

            // update the resolved type argument
            if (resolvedTypeArgument != null) {
                resolvedArguments[i] = (Class<?>) resolvedTypeArgument;
            }
        } else {
