/**
 * Writes a series of utf8-encoded bytes to the linked buffer.
 *
 * @param bytes the array of bytes to write
 * @param lb the linked buffer to write the bytes to
 * @param isLittleEndian whether the bytes should be written in little-endian byte order
 */
public static void writeBytes(final byte[] bytes, final LinkedBuffer lb, final boolean isLittleEndian) {
    // Check the length of the byte array
    int length = bytes.length;
    if (length == 0) {
        // Return early if the byte array is empty
        return;
    }

    // Compute the address of the next available bytes
    long address = lb.getAddress();

    // Check the endianness of the write operation
    if (isLittleEndian) {
        // Write the bytes in little-endian order
        for (int i = 0; i < length; i++) {
            lb.putByte(address++, bytes[i]);
        }
    } else {
        // Write the bytes in big-endian order
        for (int i = length - 1; i >= 0; i--) {
            lb.putByte(address++, bytes[i]);
        }
    }

    // Update the address of the linked buffer
    lb.setAddress(address);
}

