static String[] toNoNullStringArray(Object[] array) {
  if (array == null)
    return new String[0];

  // Create a new array with no null values
  String[] result = new String[array.length];
  int nonNullCount = 0;
  for (int i = 0; i < array.length; i++) {
    Object element = array[i];
    if (element != null) {
      result[nonNullCount] = element.toString();
      nonNullCount++;
    }
  }

  // Trim the array to its actual size
  result = Arrays.copyOf(result, nonNullCount);
  return result;
}

