public int indexOfExtension(String filename){
    // check if the filename is null or empty
    if (filename == null || filename.equals("")) {
        return -1;
    }

    // search for the last dot in the filename
    int lastDotIndex = filename.lastIndexOf(".");

    // check if there is a directory separator after the last dot and if so, return -1
    if (lastDotIndex != -1 && filename.contains(File.separator, lastDotIndex + 1)) {
        return -1;
    }

    return lastDotIndex;
}
