public static List<ThreadSnapshot> parseFromFileWithTimeRange( File file,  List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

         List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

         try (BufferedReader reader = new BufferedReader(new FileReader(file))) {

             String line;

             while ((line = reader.readLine()) != null) {

                  // Split the line into tokens
                  String[] tokens = line.split("\\s+");

                  // Check if the line contains the expected number of tokens and the first token is "TS"
                  if (tokens.length != 7 || !tokens[0].equals("TS")) {
                      continue;
                  }

                  // Extract the thread id, start time, and thread name from the line
                  int threadId = Integer.parseInt(tokens[1]);
                  long startTime = Long.parseLong(tokens[2]);
                  String threadName = tokens[3];

                  // Check if the current time range is within the expected range
                  if (!isInTimeRange( timeRanges, startTime)) {
                      continue;
                  }

                  // Create a new ThreadSnapshot object and add it to the list
                  ThreadSnapshot snapshot = new ThreadSnapshot( threadId, startTime, threadName);
                  threadSnapshots.add(snapshot);
             }
         } catch (IOException e) {
             e.printStackTrace();
         }

         return threadSnapshots;
     }

     private static boolean isInTimeRange(List<ProfileAnalyzeTimeRange> timeRanges, long startTime) {
         for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
             long start = timeRange.getStart();
             long end = timeRange.getEnd();
             if (startTime >= start && startTime <= end) {
                 return true;
             }
         }
         return false;
     }
